repo_files.circuit_breaker.py:
"""Service circuit breaker trip monitor."""

class CircuitBreaker:
    def __init__(self, failure_threshold: int = 5):
        self.failure_threshold = failure_threshold
        self.consecutive_failures = 0
        self.tripped = False

    def record_failure(self) -> None:
        self.consecutive_failures += 1
        if self.consecutive_failures >= self.failure_threshold:
            self.tripped = True

    def record_success(self) -> None:
        self.consecutive_failures = 0
        self.tripped = False

repo_files.transport.py:
"""Virtual HTTP transport layer."""

from typing import Callable, Dict


class VirtualTransport:
    def __init__(self):
        self.request_timestamps: list[float] = []

    def send(self, ts: float, action: Callable[[], str]) -> str:
        self.request_timestamps.append(ts)
        return action()

repo_files.client.py:
"""Resilient RPC client executing retries."""

from typing import Any, Callable
from circuit_breaker import CircuitBreaker
from policy import RetryPolicy
from transport import VirtualTransport


class StormResistantClient:
    def __init__(self, policy: RetryPolicy, cb: CircuitBreaker, transport: VirtualTransport):
        self.policy = policy
        self.cb = cb
        self.transport = transport
        self.clock: float = 1000.0

    def call(self, fn: Callable[[], str], seed: int = 42) -> str:
        for attempt in range(self.policy.max_retries + 1):
            if self.cb.tripped:
                raise RuntimeError("Circuit breaker is open")
            try:
                res = self.transport.send(self.clock, fn)
                self.cb.record_success()
                return res
            except Exception as e:
                self.cb.record_failure()
                if attempt == self.policy.max_retries:
                    raise e
                delay = self.policy.get_backoff(attempt, seed)
                self.clock += delay
        raise RuntimeError("Retry loop terminated unexpectedly")

reference_fix.jitter.py:
"""Exponential backoff with full jitter calculation."""

from typing import Tuple


class BackoffJitter:
    def __init__(self, base_ms: float = 100.0, max_ms: float = 5000.0, factor: float = 2.0):
        self.base_ms = base_ms
        self.max_ms = max_ms
        self.factor = factor

    def calculate_delay(self, attempt: int, seed: int = 42) -> float:
        cap = min(self.max_ms, self.base_ms * (self.factor ** attempt))
        # Ensure positive deterministic jitter non-zero delay across all seeds
        jitter_val = (seed % int(cap)) if int(cap) > 0 else 0
        return max(self.base_ms / 2.0, float(jitter_val + 1.0))
